import{_ as n,o,c as e,a4 as t}from"./chunks/framework.BAxM5-cj.js";const g=JSON.parse('{"title":"CHECK-LIST: TỪ WIREFRAME ĐẾN CODE (REACT + SHADCN/UI)","description":"","frontmatter":{},"headers":[],"relativePath":"Report_DA-E08/wireframe_to_code_checklist.md","filePath":"Report_DA-E08/wireframe_to_code_checklist.md"}'),a={name:"Report_DA-E08/wireframe_to_code_checklist.md"};function l(c,i,h,r,d,s){return o(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="check-list-tu-wireframe-đen-code-react-shadcn-ui" tabindex="-1">CHECK-LIST: TỪ WIREFRAME ĐẾN CODE (REACT + SHADCN/UI) <a class="header-anchor" href="#check-list-tu-wireframe-đen-code-react-shadcn-ui" aria-label="Permalink to &quot;CHECK-LIST: TỪ WIREFRAME ĐẾN CODE (REACT + SHADCN/UI)&quot;">​</a></h1><p><strong>Dự án:</strong> BrandHub MVP<br><strong>Mục tiêu:</strong> Hướng dẫn quy trình chuẩn hóa từng bước để lập trình viên Frontend chuyển đổi từ bản vẽ wireframe Figma sang mã nguồn React thực tế sử dụng tối đa thư viện <code>shadcn/ui</code> có sẵn.</p><hr><h2 id="giai-đoan-1-figma-audit-phan-tich-component" tabindex="-1">GIAI ĐOẠN 1: FIGMA AUDIT &amp; PHÂN TÍCH COMPONENT <a class="header-anchor" href="#giai-đoan-1-figma-audit-phan-tich-component" aria-label="Permalink to &quot;GIAI ĐOẠN 1: FIGMA AUDIT &amp; PHÂN TÍCH COMPONENT&quot;">​</a></h2><ul><li>[ ] <strong>1.1. Xác định Cấu trúc Layout chính (Layout Shell):</strong><ul><li>[ ] Phân tích xem màn hình dùng bố cục Sidebar cố định (Dashboard, Workspace, Calendar, Analytics) hay layout toàn màn hình (Login).</li><li>[ ] Nhận diện các vùng có thể co giãn, thu gọn (ví dụ: AI Generation Panel bên trái và Post Preview bên phải trong EditorPage).</li></ul></li><li>[ ] <strong>1.2. Liệt kê Component shadcn/ui cần tải thêm:</strong><ul><li>[ ] Đối chiếu bản wireframe với danh mục thư viện shadcn/ui hiện có trong <code>src/app/components/ui</code>.</li><li>[ ] Đánh dấu các component mới cần thêm (ví dụ: <code>Dialog</code>, <code>Progress</code>, <code>Switch</code>, <code>Slider</code>, <code>Carousel</code>, <code>HoverCard</code>, <code>AspectRatio</code>).</li></ul></li><li>[ ] <strong>1.3. Xác định các Component Tuỳ biến (Custom components):</strong><ul><li>[ ] Xác định các phần tử giao diện phức tạp không có sẵn trong shadcn/ui để lên kế hoạch build riêng: <ul><li>[ ] <code>PostSimulator.tsx</code> (Mô phỏng Feed Facebook/Instagram/TikTok).</li><li>[ ] <code>ModelLibraryDialog.tsx</code> (Hộp thoại chọn người mẫu AI từ hệ thống).</li><li>[ ] <code>TimelineCalendar.tsx</code> (Lịch đăng bài dạng Timeline dọc cho mobile 375px).</li></ul></li></ul></li></ul><hr><h2 id="giai-đoan-2-setup-moi-truong-them-component" tabindex="-1">GIAI ĐOẠN 2: SETUP MÔI TRƯỜNG &amp; THÊM COMPONENT <a class="header-anchor" href="#giai-đoan-2-setup-moi-truong-them-component" aria-label="Permalink to &quot;GIAI ĐOẠN 2: SETUP MÔI TRƯỜNG &amp; THÊM COMPONENT&quot;">​</a></h2><ul><li>[ ] <strong>2.1. Cài đặt thêm shadcn/ui component qua CLI:</strong><ul><li>Chạy lệnh cài đặt các component cần thiết cho luồng Editor, Calendar và Portal:</li></ul><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npx shadcn@latest add dialog tooltip slider </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">switch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> progress carousel hover</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">card aspect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ratio sheet</span></span></code></pre></div></li><li>[ ] <strong>2.2. Kiểm tra File cấu hình Tailwind &amp; CSS Variables:</strong><ul><li>[ ] Đảm bảo các token màu sắc (<code>--background</code>, <code>--primary</code>, <code>--border</code>, v.v.) trong <code>src/styles</code> hoạt động chính xác cả ở chế độ Light/Dark mode.</li><li>[ ] Kiểm tra font chữ (<code>font-sans</code>, <code>font-mono</code>) đã được mapping đúng theo CSS variables chưa.</li></ul></li></ul><hr><h2 id="giai-đoan-3-xay-dung-khung-layout-layout-shell" tabindex="-1">GIAI ĐOẠN 3: XÂY DỰNG KHUNG LAYOUT (LAYOUT SHELL) <a class="header-anchor" href="#giai-đoan-3-xay-dung-khung-layout-layout-shell" aria-label="Permalink to &quot;GIAI ĐOẠN 3: XÂY DỰNG KHUNG LAYOUT (LAYOUT SHELL)&quot;">​</a></h2><ul><li>[ ] <strong>3.1. Dựng Layout Sidebar &amp; Header:</strong><ul><li>[ ] Sử dụng các component <code>Sidebar</code> gốc để thiết lập thanh menu bên trái.</li><li>[ ] Cấu hình Workspace Switcher bằng <code>DropdownMenu</code> với trigger là một button hiển thị chevrons-up-down.</li><li>[ ] Dựng Header chứa <code>Breadcrumb</code> điều hướng động và Popover thông báo (<code>NotificationPopover</code>).</li></ul></li><li>[ ] <strong>3.2. Triển khai Layout Cột Co Giãn (cho Editor Page):</strong><ul><li>[ ] Sử dụng <code>ResizablePanelGroup</code> làm container chính.</li><li>[ ] Chia thành 3 <code>ResizablePanel</code> (Trái: AI Panel, Giữa: Soạn thảo, Phải: Preview).</li><li>[ ] Sử dụng <code>ResizableHandle</code> đi kèm thuộc tính <code>withHandle</code> để tạo đường kéo giãn trực quan.</li></ul></li></ul><hr><h2 id="giai-đoan-4-lap-rap-ui-chi-tiet-custom-simulators" tabindex="-1">GIAI ĐOẠN 4: LẮP RÁP UI CHI TIẾT &amp; CUSTOM SIMULATORS <a class="header-anchor" href="#giai-đoan-4-lap-rap-ui-chi-tiet-custom-simulators" aria-label="Permalink to &quot;GIAI ĐOẠN 4: LẮP RÁP UI CHI TIẾT &amp; CUSTOM SIMULATORS&quot;">​</a></h2><ul><li>[ ] <strong>4.1. Triển khai AI Generation Panel (Cột Trái Editor):</strong><ul><li>[ ] Dựng tab chuyển đổi Chữ/Ảnh/Video bằng <code>Tabs</code>.</li><li>[ ] Dựng danh sách tài liệu Request Assets bằng thẻ <code>Card</code> chứa ảnh sản phẩm được bọc trong <code>AspectRatio</code> kèm nút <code>Checkbox</code> chọn.</li><li>[ ] Tích hợp nút mở Thư viện AI Model bằng <code>Dialog</code>. Khi mở ra, render Grid chứa danh sách ảnh model dạng <code>Avatar</code>, bộ lọc <code>Select</code> và cuộn bằng <code>ScrollArea</code>.</li></ul></li><li>[ ] <strong>4.2. Triển khai Editor Area (Cột Giữa Editor):</strong><ul><li>[ ] Dựng form nhập tiêu đề bài viết bằng <code>Input</code> và text area soạn thảo caption bằng <code>Textarea</code> hoặc rich text editor.</li><li>[ ] Thêm khu vực hiển thị các Assets đã chọn (Product + Model) dạng Card nhỏ.</li><li>[ ] Thêm thanh tiến trình <code>Progress</code> sinh ảnh/video của AI kèm Badge mô tả tiến độ.</li><li>[ ] Dựng <code>Carousel</code> hiển thị danh sách ảnh kết quả do AI sinh ra (AI Generation History) kèm nút &quot;Áp dụng&quot; và &quot;Bỏ qua&quot;.</li></ul></li><li>[ ] <strong>4.3. Dựng Giao Diện Mô Phỏng (Post Simulator - Cột Phải):</strong><ul><li>[ ] Tạo file component riêng <code>post-simulator.tsx</code>.</li><li>[ ] Mô phỏng giao diện Facebook: Thiết kế Card có Avatar brand, tên thương hiệu, thời gian đăng bài, text caption và phần hình ảnh 1:1 hoặc link preview.</li><li>[ ] Mô phỏng giao diện TikTok/Instagram: Khung dọc tỷ lệ 9:16 có nút thả tim, bình luận giả lập.</li></ul></li></ul><hr><h2 id="giai-đoan-5-phan-quyen-giao-dien-role-based-rendering" tabindex="-1">GIAI ĐOẠN 5: PHÂN QUYỀN GIAO DIỆN (ROLE-BASED RENDERING) <a class="header-anchor" href="#giai-đoan-5-phan-quyen-giao-dien-role-based-rendering" aria-label="Permalink to &quot;GIAI ĐOẠN 5: PHÂN QUYỀN GIAO DIỆN (ROLE-BASED RENDERING)&quot;">​</a></h2><ul><li>[ ] <strong>5.1. Triển khai Auth Context hoặc Hook phân quyền:</strong><ul><li>[ ] Xây dựng hook <code>useUser</code> để lấy thông tin vai trò hiện tại (<code>ROLE_AGENCY_OWNER</code>, <code>ROLE_CONTENT_CREATOR</code>, <code>ROLE_BRAND_CLIENT</code>, v.v.).</li></ul></li><li>[ ] <strong>5.2. Điều khiển Ẩn/Hiện phần tử (Visibility Matrix):</strong><ul><li>[ ] <strong>Trong Editor Page:</strong><ul><li>[ ] Nếu là <code>CREATOR</code>: Hiện nút &quot;Gửi AM duyệt&quot; (<code>Submit to AM</code>). Ẩn thanh công cụ duyệt bài.</li><li>[ ] Nếu là <code>AM</code>: Ẩn nút &quot;Gửi AM duyệt&quot;. Hiện thanh công cụ duyệt bài ở chân trang Preview (Gồm nút &quot;Phê duyệt&quot; và nút &quot;Từ chối&quot; mở Dialog nhập feedback).</li></ul></li><li>[ ] <strong>Trong Workspace Page:</strong><ul><li>[ ] Ẩn các nút &quot;Xoá Workspace&quot; hoặc &quot;Cấu hình AI Credits&quot; nếu người dùng không phải là <code>AGENCY_OWNER</code>.</li><li>[ ] Chặn truy cập (Redirect về Client Portal) nếu là <code>BRAND_CLIENT</code>.</li></ul></li></ul></li></ul><hr><h2 id="giai-đoan-6-state-management-du-lieu-mock-dummy-state" tabindex="-1">GIAI ĐOẠN 6: STATE MANAGEMENT &amp; DỮ LIỆU MOCK (DUMMY STATE) <a class="header-anchor" href="#giai-đoan-6-state-management-du-lieu-mock-dummy-state" aria-label="Permalink to &quot;GIAI ĐOẠN 6: STATE MANAGEMENT &amp; DỮ LIỆU MOCK (DUMMY STATE)&quot;">​</a></h2><ul><li>[ ] <strong>6.1. Quản lý trạng thái Form &amp; AI Generation:</strong><ul><li>[ ] Tạo state quản lý: Prompt đầu vào, Ảnh sản phẩm đang chọn, Model đang chọn, Tiến độ AI loading (<code>boolean</code>), Danh sách ảnh kết quả sinh ra (<code>string[]</code>).</li></ul></li><li>[ ] <strong>6.2. Thiết lập Trạng thái Tải dữ liệu (Loading/Skeleton):</strong><ul><li>[ ] Khi <code>aiLoading === true</code>, hiển thị component <code>Skeleton</code> đè lên vùng soạn thảo và Preview để ngăn tương tác.</li></ul></li><li>[ ] <strong>6.3. Tích hợp Toast Thông Báo:</strong><ul><li>[ ] Gọi hàm <code>toast()</code> từ hook <code>useToast</code> khi Creator bấm gửi bài duyệt thành công, khi AM phê duyệt bài đăng, hoặc khi tải tài liệu RAG lên thành công.</li></ul></li></ul><hr><h2 id="giai-đoan-7-toi-uu-hoa-responsive-mobile-375px" tabindex="-1">GIAI ĐOẠN 7: TỐI ƯU HÓA RESPONSIVE &amp; MOBILE (375PX) <a class="header-anchor" href="#giai-đoan-7-toi-uu-hoa-responsive-mobile-375px" aria-label="Permalink to &quot;GIAI ĐOẠN 7: TỐI ƯU HÓA RESPONSIVE &amp; MOBILE (375PX)&quot;">​</a></h2><ul><li>[ ] <strong>7.1. Ẩn/Hiện Panel theo Breakpoint:</strong><ul><li>[ ] Sử dụng các tiền tố Tailwind (<code>hidden md:block</code>, <code>block md:hidden</code>) để ẩn AI Panel và Preview Panel trên màn hình di động, dồn toàn bộ giao diện thành 1 cột chính.</li><li>[ ] Dùng <code>Sheet</code> (Drawer di động) để chứa Sidebar điều hướng khi người dùng bấm vào Hamburger Menu ở Header.</li></ul></li><li>[ ] <strong>7.2. Tối ưu hóa Calendar Mobile:</strong><ul><li>[ ] Ẩn lưới lịch tháng 30 ngày trên màn hình dưới <code>md</code>.</li><li>[ ] Render thanh 7 ngày trong tuần trượt ngang (<code>ScrollArea</code> + Flex).</li><li>[ ] Render timeline dọc chứa các Card bài đăng chi tiết trong ngày được chọn.</li></ul></li><li>[ ] <strong>7.3. Triển khai Sticky Bottom Bar cho Post Preview:</strong><ul><li>[ ] Trên mobile, khi ở view Post Preview, cố định nút Phê duyệt và Từ chối bằng class <code>fixed/sticky bottom-0 left-0 right-0 border-t bg-background p-3 flex gap-2</code>.</li></ul></li></ul>',23)])])}const m=n(a,[["render",l]]);export{g as __pageData,m as default};
